#include <stdio.h>
#include <string.h>

#define MAX 50
#define FILENAME "students.dat"

typedef struct {
    int roll;
    char name[40];
    float marks;
} Student;

Student list[MAX];
int count = 0;

void loadRecords(void) {
    FILE *fp = fopen(FILENAME, "rb");
    if (fp == NULL) {
        return;                     // first run: no file yet
    }
    count = fread(list, sizeof(Student), MAX, fp);
    fclose(fp);
}

void saveRecords(void) {
    FILE *fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        printf("Could not save!\n");
        return;
    }
    fwrite(list, sizeof(Student), count, fp);
    fclose(fp);
}

void clearInput(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF) { }
}

void addStudent(void) {
    if (count == MAX) {
        printf("Register is full.\n");
        return;
    }
    Student s;
    printf("Roll number: ");
    scanf("%d", &s.roll);
    clearInput();
    printf("Name: ");
    fgets(s.name, sizeof(s.name), stdin);
    s.name[strcspn(s.name, "\n")] = '\0';
    printf("Marks: ");
    scanf("%f", &s.marks);
    clearInput();
    list[count] = s;
    count++;
    saveRecords();
    printf("Saved %s.\n", s.name);
}

void showAll(void) {
    if (count == 0) {
        printf("No records yet.\n");
        return;
    }
    printf("%-6s %-20s %s\n", "Roll", "Name", "Marks");
    for (int i = 0; i < count; i++) {
        printf("%-6d %-20s %.1f\n", list[i].roll, list[i].name, list[i].marks);
    }
}

int main(void) {
    int choice = 0;
    loadRecords();
    do {
        printf("\n1. Add  2. Show all  3. Exit\nChoice: ");
        if (scanf("%d", &choice) != 1) {
            clearInput();
            printf("Please type a number.\n");
            continue;
        }
        clearInput();
        switch (choice) {
            case 1: addStudent(); break;
            case 2: showAll();    break;
            case 3: printf("Bye!\n"); break;
            default: printf("Pick 1, 2 or 3.\n");
        }
    } while (choice != 3);
    return 0;
}

